from pathlib import Path
p=Path('outputs/community-connect/index.html');s=p.read_text(encoding='utf-8-sig')
s=s.replace('rural community routes chosen by participating employees','5-mile default radius plus employee-added rural map routes').replace('without a fixed distance cutoff','within the default radius or an employee-added map route')
s=s.replace('value="Hazel Mountain demo corridor"','value="Demo neighborhood"').replace('id="estm" type="number" min="0.1" step="0.1" value="18"','id="estm" type="number" min="0.1" step="0.1" value="4.5"').replace('id="estt" type="number" min="1" value="45"','id="estt" type="number" min="1" value="30"')
s=s.replace('No fixed service radius. Dispatch offers depend on a willing employee, safe access, coverage and available paid work capacity.','The 5-mile radius applies unless an employee adds a route to the delivery map. Select that corridor for a rural exception. Safe access, coverage and paid work capacity still apply.')
s=s.replace('<label>Route / neighborhood (synthetic only)','<label>Delivery coverage <select id="routeid"><option value="">Within default 5-mile radius</option>${state.routes.map(x=>`<option value="${x.id}">${esc(x.name)} · ${x.miles} miles · employee ${x.employee}</option>`).join(\'\')}</select></label><label>Route / neighborhood (synthetic only)')
s=s.replace("let html='';","let html=routeMap();")
s=s.replace("route:document.querySelector('#route').value,","route_id:document.querySelector('#routeid').value,route:document.querySelector('#route').value,")
s=s.replace("async function logout()",'''function routeMap(){const dirs={N:[0,-1],NE:[.7,-.7],E:[1,0],SE:[.7,.7],S:[0,1],SW:[-.7,.7],W:[-1,0],NW:[-.7,-.7]};let lines=state.routes.map(x=>{let d=dirs[x.direction],px=250+d[0]*170,py=180+d[1]*135;return `<line x1="250" y1="180" x2="${px}" y2="${py}" stroke="#c92032" stroke-width="3"/><circle cx="${px}" cy="${py}" r="7" fill="#c92032"/><text x="${px}" y="${py-14}" text-anchor="middle" font-size="13" fill="#123269">Route ${x.id} · ${x.miles} mi</text>`}).join('');return `<section><h3>Delivery coverage map</h3><p>Default 5-mile radius. Employee-added routes extend coverage along the listed corridors. Synthetic schematic only, not a navigation map or address validation.</p><svg viewBox="0 0 500 360" role="img" aria-label="Schematic delivery coverage map" style="width:100%;max-width:640px;background:#f3f5fa"><circle cx="250" cy="180" r="65" fill="#e1e9f8" stroke="#123269" stroke-dasharray="5 4"/>${lines}<circle cx="250" cy="180" r="9" fill="#123269"/><text x="250" y="205" text-anchor="middle" fill="#123269">Demo store · 5-mile radius</text></svg>${state.routes.map(x=>`<p><b>Route ${x.id}: ${esc(x.name)}</b> · ${x.miles} miles · ${x.minutes} min · added by employee ${x.employee}</p>`).join('')}${state.role==='employee'?`<h3>Add a route you can serve</h3><p>Adding a route creates a coverage exception, not a commitment to accept every order.</p><label>Synthetic corridor name <input id="rn" placeholder="Mountain neighbors demo route" maxlength="100"></label><label>Delivery miles <input id="rm" type="number" min="0.1" step="0.1" value="18"></label><label>Delivery minutes <input id="rt" type="number" min="1" value="45"></label><label>Map direction <select id="rd">${Object.keys(dirs).map(k=>`<option>${k}</option>`).join('')}</select></label><button onclick="act('add_route',null,{name:document.querySelector('#rn').value,miles:document.querySelector('#rm').value,minutes:document.querySelector('#rt').value,direction:document.querySelector('#rd').value})">Add to delivery map</button>`:''}</section>`}
async function logout()''')
p.write_text(s,encoding='utf-8')
